from jsonb_populate_recordset(null::public.catalogs, $seed$[{"museum_id":"henan","language":"zh","museum_name":"河南博物院","location":"河南郑州","text_credit":null,"categories":["青铜器","陶瓷","玉器·金器·兵器","乐器","壁画"]}]$seed$::jsonb)
